def custo_entrada(n_chamados, tokens_por_chamado, preco_por_milhao):
    total_tokens = n_chamados * tokens_por_chamado
    return (total_tokens / 1_000_000) * preco_por_milhao

Classifique o chamado em UMA categoria: entrega, pagamento, produto, cancelamento, outros.
Responda APENAS com JSON válido:
{"categoria": "<uma das categorias>", "id_pedido": <numero ou null>}

CATEGORIAS = {"entrega", "pagamento", "produto", "cancelamento", "outros"}

def valida(resp, texto_original):
    if resp.get("categoria") not in CATEGORIAS:
        raise ValueError("categoria invalida")
    idp = resp.get("id_pedido")
    if idp is not None and str(idp) not in texto_original:
        raise ValueError("id_pedido nao encontrado no texto")
    return resp

